BEGIN
 SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]'::jsonb) INTO actual FROM (SELECT r.relname AS table,i.relname AS index,pg_get_indexdef(i.oid) AS definition,x.indisvalid AS valid,x.indisready AS ready FROM pg_index x JOIN pg_class r ON r.oid=x.indrelid JOIN pg_class i ON i.oid=x.indexrelid JOIN pg_namespace n ON n.oid=r.relnamespace WHERE n.nspname='public' AND r.relname=ANY(ARRAY['agente_users','bitacora_actividad','client_users','clientes','costeo_agentes','costeo_rutas','costeo_tarifa_recargos','costeo_tarifas','cotizacion_costos','cotizacion_versiones','cotizaciones','crm_empresas','crm_etapas_pipeline','crm_historial_etapas','crm_leads','crm_motivos_perdida','crm_notificaciones','crm_oportunidades','crm_solicitudes_pricing','embarques','factura_series','facturas','folio_secuencias','navieras','notificaciones_cliente','organization_members','organizations','proformas','proveedores','puertos','super_admin_org_activa','tipos_contenedor','user_roles']::text[]) AND i.relname <> 'cotizaciones_pricing_solicitud_idx') x;
