BEGIN
 SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]'::jsonb) INTO actual FROM (SELECT n.nspname AS schema_name,c.relname AS relation_name,p.polname AS name,p.polpermissive AS permissive,p.polcmd AS command,ARRAY(SELECT CASE WHEN r=0 THEN 'PUBLIC' ELSE pg_get_userbyid(r)::text END FROM unnest(p.polroles) r ORDER BY 1) AS roles,pg_get_expr(p.polqual,p.polrelid) AS using_expression,pg_get_expr(p.polwithcheck,p.polrelid) AS check_expression FROM pg_policy p JOIN pg_class c ON c.oid=p.polrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname=ANY(ARRAY['agente_users','bitacora_actividad','client_users','clientes','costeo_agentes','costeo_rutas','costeo_tarifa_recargos','costeo_tarifas','cotizacion_costos','cotizacion_versiones','cotizaciones','crm_empresas','crm_etapas_pipeline','crm_historial_etapas','crm_leads','crm_motivos_perdida','crm_notificaciones','crm_oportunidades','crm_solicitudes_pricing','embarques','factura_series','facturas','folio_secuencias','navieras','notificaciones_cliente','organization_members','organizations','proformas','proveedores','puertos','super_admin_org_activa','tipos_contenedor','user_roles']::text[])) x;
 SELECT coalesce(jsonb_agg(v ORDER BY v::text),'[]'::jsonb) INTO expected FROM jsonb_array_elements(expected) v;
 IF actual IS DISTINCT FROM expected THEN
  RAISE EXCEPTION 'C06: all scoped policies without expression normalization: catalog mismatch' USING DETAIL = jsonb_build_object('actual_count',jsonb_array_length(actual),'expected_count',jsonb_array_length(expected),'unexpected',(SELECT coalesce(jsonb_agg(v),'[]') FROM (SELECT value AS v FROM jsonb_array_elements(actual) EXCEPT SELECT value FROM jsonb_array_elements(expected)) q),'missing',(SELECT coalesce(jsonb_agg(v),'[]') FROM (SELECT value AS v FROM jsonb_array_elements(expected) EXCEPT SELECT value FROM jsonb_array_elements(actual)) q))::text;
 END IF;
 RAISE NOTICE 'PASS C06: all scoped policies without expression normalization';
