_cliente"}]$expected$::jsonb;
BEGIN
 SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]'::jsonb) INTO actual FROM (SELECT c.relname AS table,t.tgname AS name,t.tgenabled AS enabled,pg_get_triggerdef(t.oid,true) AS definition,t.tgfoid::regprocedure::text AS function FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname=ANY(ARRAY['bitacora_actividad','costeo_tarifas','cotizacion_costos','cotizacion_versiones','cotizaciones','crm_empresas','crm_historial_etapas','crm_leads','crm_notificaciones','crm_oportunidades','crm_solicitudes_pricing','folio_secuencias','notificaciones_cliente']::text[]) AND NOT t.tgisinternal AND t.tgname <> 'trg_guard_cotizacion_origen_pricing') x;
 SELECT coalesce(jsonb_agg(v ORDER BY v::text),'[]'::jsonb) INTO expected FROM jsonb_array_elements(expected) v;
 IF actual IS DISTINCT FROM expected THEN
  RAISE EXCEPTION 'C07: all 45 original user triggers on thirteen mutation tables: catalog mismatch' USING DETAIL = jsonb_build_object('actual_count',jsonb_array_length(actual),'expected_count',jsonb_array_length(expected),'unexpected',(SELECT coalesce(jsonb_agg(v),'[]') FROM (SELECT value AS v FROM jsonb_array_elements(actual) EXCEPT SELECT value FROM jsonb_array_elements(expected)) q),'missing',(SELECT coalesce(jsonb_agg(v),'[]') FROM (SELECT value AS v FROM jsonb_array_elements(expected) EXCEPT SELECT value FROM jsonb_array_elements(actual)) q))::text;
 END IF;
 RAISE NOTICE 'PASS C07: all 45 original user triggers on thirteen mutation tables';
END $assert$;
