 SELECT coalesce(jsonb_agg(v ORDER BY v::text),'[]'::jsonb) INTO expected FROM jsonb_array_elements(expected) v;
 IF actual IS DISTINCT FROM expected THEN
  RAISE EXCEPTION 'C15: exact candidate-pinned pg_policies guard input: catalog mismatch' USING DETAIL = jsonb_build_object('actual_count',jsonb_array_length(actual),'expected_count',jsonb_array_length(expected),'unexpected',(SELECT coalesce(jsonb_agg(v),'[]') FROM (SELECT value AS v FROM jsonb_array_elements(actual) EXCEPT SELECT value FROM jsonb_array_elements(expected)) q),'missing',(SELECT coalesce(jsonb_agg(v),'[]') FROM (SELECT value AS v FROM jsonb_array_elements(expected) EXCEPT SELECT value FROM jsonb_array_elements(actual)) q))::text;
 END IF;
 RAISE NOTICE 'PASS C15: exact candidate-pinned pg_policies guard input';
END $assert$;

-- Exact helper behavior is SQL-level claim interpretation, not JWT validation.
DO $assert$
BEGIN
 PERFORM set_config('request.jwt.claim.sub','',true);
 PERFORM set_config('request.jwt.claim.role','',true);
 PERFORM set_config('request.jwt.claim','',true);
 PERFORM set_config('request.jwt.claims','',true);
 IF auth.uid() IS NOT NULL OR auth.role() IS NOT NULL OR auth.jwt() IS NOT NULL THEN RAISE EXCEPTION 'A01: empty claims must be null'; END IF;
 PERFORM set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000010","role":"authenticated","email":"seller@replay.invalid"}',true);
 IF auth.uid() IS DISTINCT FROM '10000000-0000-4000-8000-000000000010'::uuid OR auth.role() IS DISTINCT FROM 'authenticated' OR auth.jwt()->>'email' IS DISTINCT FROM 'seller@replay.invalid' THEN RAISE EXCEPTION 'A01: JSON fallback failed'; END IF;
 PERFORM set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000011',true);
 PERFORM set_config('request.jwt.claim.role','anon',true);
 PERFORM set_config('request.jwt.claim','{"marker":"singular"}',true);
 IF auth.uid() IS DISTINCT FROM '10000000-0000-4000-8000-000000000011'::uuid OR auth.role() IS DISTINCT FROM 'anon' OR auth.jwt() IS DISTINCT FROM '{"marker":"singular"}'::jsonb THEN RAISE EXCEPTION 'A01: legacy/singular precedence failed'; END IF;
 PERFORM set_config('request.jwt.claim.sub','',true);
 PERFORM set_config('request.jwt.claim.role','',true);
 PERFORM set_config('request.jwt.claim','',true);
 IF auth.uid() IS DISTINCT FROM '10000000-0000-4000-8000-000000000010'::uuid OR auth.role() IS DISTINCT FROM 'authenticated' THEN RAISE EXCEPTION 'A01: fallback restoration failed'; END IF;
 RAISE NOTICE 'PASS A01: exact auth empty, JSON fallback, legacy and singular precedence';
END $assert$;

SET LOCAL ROLE postgres;
DO $assert$
DECLARE t record; denied boolean;
BEGIN
 SELECT * INTO t FROM public.cotizacion_totales_conceptos('[{"cantidad":2,"precio_unitario":125.50,"moneda":"USD","aplica_iva":true},{"cantidad":3,"precio_unitario":10.01,"moneda":"MXN","tasa_iva_aplicada":0.08}]');
 IF ROW(t.subtotal_usd,t.iva_usd,t.total_usd,t.subtotal_mxn,t.iva_mxn,t.total_mxn) IS DISTINCT FROM ROW(251::numeric,40.16::numeric,291.16::numeric,30.03::numeric,2.40::numeric,32.43::numeric) THEN RAISE EXCEPTION 'A02: calculation/rounding mismatch'; END IF;
 SELECT * INTO t FROM public.cotizacion_totales_conceptos(NULL);
 IF ROW(t.subtotal_usd,t.iva_usd,t.total_usd,t.subtotal_mxn,t.iva_mxn,t.total_mxn) IS DISTINCT FROM ROW(0::numeric,0::numeric,0::numeric,0::numeric,0::numeric,0::numeric) THEN RAISE EXCEPTION 'A02: null input totals'; END IF;
 denied:=false;
 BEGIN PERFORM public.cotizacion_totales_conceptos('{}'); EXCEPTION WHEN check_violation THEN denied:=SQLERRM LIKE 'LC_COTIZACION_CONCEPTO_INVALIDO:%'; END;
 IF NOT denied THEN RAISE EXCEPTION 'A02: non-array input not rejected'; END IF;
 denied:=false;
 BEGIN PERFORM public.cotizacion_totales_conceptos('[{"cantidad":-1,"precio_unitario":5}]'); EXCEPTION WHEN check_violation THEN denied:=SQLERRM LIKE 'LC_COTIZACION_CONCEPTO_INVALIDO:%'; END;
 IF NOT denied THEN RAISE EXCEPTION 'A02: negative quantity not rejected'; END IF;
 denied:=false;
 BEGIN PERFORM public.cotizacion_totales_conceptos('[{"cantidad":1,"precio_unitario":5,"moneda":"EUR"}]'); EXCEPTION WHEN check_violation THEN denied:=SQLERRM LIKE 'LC_COTIZACION_MONEDA_NO_SOPORTADA:%'; END;
 IF NOT denied THEN RAISE EXCEPTION 'A02: unsupported currency not rejected'; END IF;
 RAISE NOTICE 'PASS A02: mixed-currency calculation, rounding, null and invalid inputs';
END $assert$;

