DO $assert$
DECLARE s public.crm_solicitudes_pricing%ROWTYPE; c public.cotizaciones%ROWTYPE; x public.cotizacion_costos%ROWTYPE;
BEGIN
 SELECT * INTO STRICT s FROM public.crm_solicitudes_pricing WHERE id='10000000-0000-4000-8000-000000000050';
 IF s.folio IS DISTINCT FROM public._crm_folio_pricing_prefijo(now())||'0001' OR s.created_by IS DISTINCT FROM auth.uid() OR s.estado<>'borrador' OR s.enviada_at IS NOT NULL OR s.vence_at IS NOT NULL OR s.respondida_at IS NOT NULL THEN RAISE EXCEPTION 'L01: actual draft lifecycle failed'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.folio_secuencias WHERE organization_id=s.organization_id AND tipo='pricing_'||to_char(now() AT TIME ZONE 'America/Mexico_City','YYMM') AND ultimo_numero=1) THEN RAISE EXCEPTION 'L01: transactional folio counter missing'; END IF;
 SELECT * INTO STRICT c FROM public.cotizaciones WHERE id='10000000-0000-4000-8000-000000000080';
 IF c.subtotal<>251 OR c.puerto_origen_id IS DISTINCT FROM '10000000-0000-4000-8000-000000000092'::uuid OR c.puerto_destino_id IS DISTINCT FROM '10000000-0000-4000-8000-000000000093'::uuid OR c.fecha_vigencia IS DISTINCT FROM (c.created_at AT TIME ZONE 'America/Mexico_City')::date + 15 OR c.created_by IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'L01: quote derivations missing'; END IF;
 SELECT * INTO STRICT x FROM public.cotizacion_costos WHERE id='10000000-0000-4000-8000-000000000085';
 IF ROW(x.costo_total,x.precio_total,x.profit,x.porcentaje_profit) IS DISTINCT FROM ROW(200::numeric,300::numeric,100::numeric,33.33::numeric) THEN RAISE EXCEPTION 'L01: stored generated cost values mismatch'; END IF;
