-- A separate read-only transaction proves that the synthetic lifecycle rolled
-- back, rather than inferring cleanup only from successful ROLLBACK syntax.
BEGIN READ ONLY;
SET LOCAL search_path = public, extensions, pg_catalog;
DO $assert$
DECLARE t text; n bigint; r text; f text;
BEGIN
 IF current_user<>'replay_bootstrap' THEN RAISE EXCEPTION 'Z01: bootstrap role not restored'; END IF;
 FOREACH t IN ARRAY ARRAY['agente_users','bitacora_actividad','client_users','clientes','costeo_agentes','costeo_rutas','costeo_tarifa_recargos','costeo_tarifas','cotizacion_costos','cotizacion_versiones','cotizaciones','crm_empresas','crm_etapas_pipeline','crm_historial_etapas','crm_leads','crm_motivos_perdida','crm_notificaciones','crm_oportunidades','crm_solicitudes_pricing','embarques','factura_series','facturas','folio_secuencias','navieras','notificaciones_cliente','organization_members','organizations','proformas','proveedores','puertos','super_admin_org_activa','tipos_contenedor','user_roles']::text[] LOOP
  EXECUTE format('SELECT count(*) FROM public.%I',t) INTO n;
  IF n<>0 THEN RAISE EXCEPTION 'Z01: rollback left % rows in %',n,t; END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM auth.users) THEN RAISE EXCEPTION 'Z01: rollback left synthetic auth identities'; END IF;
 FOREACH f IN ARRAY ARRAY['public.crm_vincular_cotizacion_cliente_pricing(uuid,uuid,uuid,uuid)','public.guard_cotizacion_origen_pricing()'] LOOP
  FOREACH r IN ARRAY ARRAY['anon','authenticated','service_role'] LOOP
   IF has_function_privilege(r,f,'EXECUTE') THEN RAISE EXCEPTION 'Z01: candidate application EXECUTE changed for %',r; END IF;
  END LOOP;
 END LOOP;
 RAISE NOTICE 'PASS Z01: all synthetic rows and side effects rolled back; candidate application EXECUTE remains revoked';
END $assert$;
ROLLBACK;
